// Legacy C-style resource management (prone to leaks)
void processWidgetRaw() {
    Widget* raw_ptr = new Widget();
    if (some_condition()) {
        // Leaks if this function throws an exception
        throw std::runtime_error("Error during processing");
    }
    delete raw_ptr; // Manual cleanup, easy to forget
}

// Modern C++ RAII with a smart pointer
void processWidgetSmart() {
    // Resource is owned by the unique_ptr
    auto smart_ptr = std::make_unique<Widget>();

    if (some_condition()) {
        // No leak! The smart_ptr destructor will be called during
        // stack unwinding, automatically deleting the Widget.
        throw std::runtime_error("Error during processing");
    }
    // No manual delete needed. Cleanup is automatic at scope exit.
}
